def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    my_def = 0
    for me, opp in history:
        if opp == 'D':
            opp_def += 1
        if me == 'D':
            my_def += 1

    last_me, last_opp = history[-1]

    if n < 10:
        return 'C'

    if n == 10:
        return 'D'
    if n == 11:
        return 'C'

    retaliatory = False
    if len(history) > 11 and history[11][1] == 'D':
        retaliatory = True

    if retaliatory:
        if last_opp == 'D':
            if last_me == 'D':
                if n > 0 and (n - opp_def) / n > 0.5:
                    return 'C'
                return 'D'
            return 'D'
        else:
            if n == 99:
                return 'D'
            return 'C'

    retaliations = 0
    for i in range(1, n):
        if history[i-1][0] == 'D' and history[i][1] == 'D':
            retaliations += 1

    if retaliations == 0:
        k = 8
    elif retaliations <= 2:
        k = 10
    else:
        k = 12

    if last_me == 'D':
        return 'C'

    if last_opp == 'D':
        return 'D'

    if (n + 1) % k == 0 and n > 11:
        return 'D'

    if n >= 95 and opp_def == 0:
        return 'D'
    if n >= 95 and (n - opp_def) / n > 0.9:
        if rng.random() < 0.5:
            return 'D'

    return 'C'
